#include <stdio.h>
#include <stdlib.h>
#include "mmt_lib.h"

// Define a threshold for the frequency of NGSetupRequest messages (e.g., 5 messages per second)
#define NGAP_SETUP_FREQUENCY_THRESHOLD 5

// Function to check the frequency of NGSetupRequest messages
// Parameters:
//   timestamp: The timestamp of the current message.
//   message_number: The message number of the current message.
// Returns:
//   1 if the frequency is above the threshold, 0 otherwise.
int check_ngap_setup_frequency(uint64_t timestamp, uint64_t message_number) {
  static uint64_t last_timestamp = 0;
  static uint64_t last_message_number = 0;
  static int message_count = 0;

  if (timestamp == last_timestamp) {
    message_count++;
  } else {
    // New time interval, reset the message count
    message_count = 1;
    last_timestamp = timestamp;
  }

  last_message_number = message_number;

  if (message_count >= NGAP_SETUP_FREQUENCY_THRESHOLD) {
    return 1; // Frequency is too high
  } else {
    return 0; // Frequency is within the acceptable range
  }
}
